static const CoeffFuncSpec *lookupCoeffFuncSpec(const char *name) {
    for (int i = 0; i < _nCoeffFuncSpecs; i++) {
        if (strcmp(name, _coeffFuncSpecs[i].name) == 0) return &_coeffFuncSpecs[i];
    }
    return NULL;
}
